int myNum = 15;

int myOtherNum = 23;

// Assign the value of myOtherNum (23) to myNum

myNum = myOtherNum;

// myNum is now 23 (was 15)

printf("%d", myNum);

// Create a variable and assign a value

int myNum = 15;

// Declare a variable without assigning a value

int myOtherNum;

// Copy the value from myNum

myOtherNum = myNum;

// myOtherNum is now 15

printf("%d", myOtherNum);

